>
  <ol class="flex flex-wrap items-center gap-2">
    {%- for item in ui_def(p['Items'], []) %}
      <li class="inline-flex items-center">
        {%- if (ui_is_set_str(ui_field(item, 'Href', '')) and not (ui_field(item, 'Disabled', false))) %}
