            {%- if ui_is_set_str(ui_field(item, 'Href', '')) %} href="{{ ui_field(item, 'Href', '') }}"{%- endif %}
            class="{{ ui_cn(['text-sm', ('font-medium' if ui_field(item, 'Current', false) else ('text-muted-foreground' if ui_field(item, 'Disabled', false) else 'text-primary underline-offset-4 hover:underline'))]) }}"
            {%- if ui_field(item, 'Current', false) %} aria-current="page"{%- endif %}
          >{{ ui_field(item, 'Label', '') }}</a>
        {%- else %}
          <span
            class="{{ ui_cn(['text-sm', ('font-medium' if ui_field(item, 'Current', false) else ('text-muted-foreground' if ui_field(item, 'Disabled', false) else 'text-primary underline-offset-4 hover:underline'))]) }}"
            {%- if ui_field(item, 'Current', false) %} aria-current="page"{%- endif %}
          >{{ ui_field(item, 'Label', '') }}</span>
        {%- endif %}
      </li>
    {%- endfor %}
  </ol>
</nav>
